import os,re,json,collections
from collections import deque as dq
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def components8(g,bg):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; res=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]!=bg and not seen[r][c]:
                q=dq([(r,c)]); seen[r][c]=True; cs=[]
                while q:
                    rr,cc=q.popleft(); cs.append((rr,cc,g[rr][cc]))
                    for dr in(-1,0,1):
                        for dc in(-1,0,1):
                            nr,nc=rr+dr,cc+dc
                            if 0<=nr<H and 0<=nc<W and not seen[nr][nc] and g[nr][nc]!=bg:
                                seen[nr][nc]=True; q.append((nr,nc))
                res.append(cs)
    return res
def f(g):
    bg=collections.Counter(x for r in g for x in r).most_common(1)[0][0]
    H,W=len(g),len(g[0])
    out=[[bg]*W for _ in range(H)]
    for cs in components8(g,bg):
        rs=[r for r,_,_ in cs]; cl=[c for _,c,_ in cs]
        bot=max(rs); right=max(cl)
        for r,c,v in cs:
            nc=c if (r==bot or c==right) else c+1
            if nc<W: out[r][nc]=v
    return out
